ext('c12_eng_ch13',[
C("🌿","घास का तिनका: छोटे में बड़ा",["साधारण चीज़ का महत्व","जीवन का रहस्य","हर पत्ती एक चमत्कार","सबमें एक जैसी साँस"],"कविता का एक सुंदर विचार है कि घास का एक तिनका भी उतना ही महत्वपूर्ण है जितना कोई बड़ा तारा या महल। कवि के लिए हर छोटी चीज़ में पूरे ब्रह्मांड की झलक है। हम अकसर बड़ी चीज़ों को देखते हैं और छोटी चीज़ों को नज़रअंदाज़ कर देते हैं। पर कवि हमें सिखाता है कि जीवन की हर चीज़, चाहे कितनी छोटी हो, चमत्कार है। यह विचार विनम्रता और प्रकृति के प्रति आदर सिखाता है।"),
Q("कवि घास के तिनके को इतना महत्व क्यों देता है?","क्योंकि उसमें जीवन और ब्रह्मांड का चमत्कार दिखाई देता है; हर छोटी चीज़ महत्वपूर्ण है","सोचिए... हरी घास हर जगह उगती है, फिर भी उसमें जीवन की पूरी शक्ति है। कवि दिखाता है कि छोटी और साधारण चीज़ें भी अनमोल हैं।"),
C("👥","'मैं' का अर्थ: व्यक्ति और समाज",["व्यक्ति से बड़ा समुदाय","अनुभव समान","मेरी भावना तुम्हारी भी","सबका आपसी जुड़ाव"],"कविता में जब कवि मैं कहता है, तो वह केवल अपनी बात नहीं करता। वह हर पाठक की ओर से बोल रहा होता है। उसका मतलब है कि जो मेरे भीतर है, वही तुम्हारे भीतर भी है। हम सबके सुख-दुख, सपने और आशाएँ एक जैसी हैं। इसलिए यह स्वयं का उत्सव असल में पूरी मानवता का उत्सव है। यह भाव हमें अहंकार से दूर और सहानुभूति के क़रीब ले जाता है।"),
Q("कविता में 'I' का क्या अर्थ है?","कवि का निजी स्वर, जो असल में हर इंसान का प्रतिनिधित्व करता है","सोचिए... कवि अपने बारे में बात करते हुए सभी के बारे में बात करता है। इसलिए 'मैं' सबका प्रतीक बन जाता है, और कविता सब पर लागू होती है।"),
C("⚖️","समानता और सम्मान",["अमीर-ग़रीब बराबर","हर पेशे का सम्मान","स्त्री-पुरुष समान","हर जीव का मूल्य"],"व्हिटमैन ने अपनी कविताओं में लोकतंत्र और समानता का गहरा भाव रखा है। उनके लिए खेत में काम करने वाला मज़दूर, नाविक, शिक्षक और राजा सब बराबर हैं। कोई पेशा छोटा या बड़ा नहीं। स्त्री और पुरुष दोनों बराबर महत्व रखते हैं। यह दृष्टि उस ज़माने में बहुत क्रांतिकारी थी, जब समाज में भेदभाव आम था। आज के भारत के संविधान में भी समानता का मूल्य यही संदेश देता है।"),
Q("व्हिटमैन की कविता में समानता का भाव कैसे दिखता है?","सभी लोग और पेशे बराबर माने गए हैं, कोई छोटा-बड़ा नहीं","उदाहरण सोचिए... कविता मज़दूर, किसान और राजा को एक सम्मान देती है। यह लोकतांत्रिक सोच व्हिटमैन की पहचान है।"),
C("📝","मुक्त छंद और सूची शैली",["तुक नहीं","लंबी पंक्तियाँ","सूची की तरह वर्णन","बातचीत जैसा लहजा"],"व्हिटमैन को मुक्त छंद का जनक माना जाता है। उनकी कविता में तुक या निश्चित मात्रा का बंधन नहीं है। पंक्तियाँ कभी लंबी, कभी छोटी, और बोलचाल जैसी बहती हैं। वे चीज़ों की लंबी सूचियाँ बनाकर दुनिया की विविधता दिखाते हैं। शैली में आत्मविश्वास और खुलापन है। इस शैली ने बाद के कई कवियों को प्रभावित किया, जिनमें भारतीय कवि भी शामिल हैं।"),
Q("मुक्त छंद की दो विशेषताएँ बताइए।","तुक या निश्चित मात्रा का बंधन नहीं; पंक्तियाँ स्वाभाविक लय में बहती हैं","याद कीजिए... इसमें न तुकबंदी की अनिवार्यता है, न गिनती के अक्षर। कवि अपनी भावना के अनुसार पंक्तियाँ लिखता है।"),
C("🌌","जीवन और मृत्यु का चक्र",["जन्म और मृत्यु साथ","प्रकृति में नवीनीकरण","मृत्यु से भय नहीं","जीवन की निरंतरता"],"कविता केवल उत्सव की बात नहीं करती, बल्कि जीवन और मृत्यु के चक्र को भी स्वीकार करती है। कवि मानता है कि हर चीज़ प्रकृति में लौट जाती है और उसी से नया जीवन उगता है, जैसे पतझड़ के बाद नई घास। इसलिए मृत्यु से डरने की ज़रूरत नहीं। यह दृष्टि हमें जीवन को पूरी तरह जीने और हर पल की क़द्र करने की प्रेरणा देती है।"),
C("🧭","आज की प्रासंगिकता",["विविध समाज में एकता","भेदभाव का विरोध","पर्यावरण से जुड़ाव","आत्मसम्मान और आत्मविश्वास"],"आज के समय में यह कविता बहुत प्रासंगिक है। जब समाज जाति, धर्म और भाषा में बँटा दिखता है, तब कविता हमें याद दिलाती है कि हम सब एक हैं। प्रकृति से बढ़ते अलगाव में यह हमें घास, पेड़ और आकाश से जुड़ना सिखाती है। यह विद्यार्थियों को अपने आप पर विश्वास और दूसरों के प्रति सम्मान का पाठ भी देती है।"),
Q("इस कविता से आप क्या सीखते हैं? दो बातें बताइए।","सबके प्रति समानता और सम्मान; प्रकृति से जुड़ाव और आत्मविश्वास","अपने शब्दों में सोचिए... कविता हमें समानता और सम्मान सिखाती है, और यह भी कि छोटी-छोटी चीज़ों और प्रकृति में सुंदरता देखें। साथ ही अपने आप पर विश्वास रखें।"),
C("✍️","उत्तर लिखने की रणनीति",["कवि और कविता का परिचय","मुख्य भाव: एकता और समानता","शैली: मुक्त छंद","आज की सीख"],"इस कविता पर उत्तर लिखते समय पहले व्हिटमैन और कविता का परिचय दीजिए। फिर मैं के अर्थ, प्रकृति से जुड़ाव और समानता का वर्णन कीजिए। भाषा और शैली में मुक्त छंद का ज़िक्र कीजिए। अंत में आज की प्रासंगिकता बताइए। अपने शब्दों में लिखिए और पंक्तियाँ ज्यों की त्यों न उतारिए।"),
],7)
